#!/usr/bin/env node
// Builds src/backend/NobleHashes.js: the unmodified CommonJS files of the pinned @noble/hashes that PBKDF2-HMAC-SHA256
// needs, wrapped so Apps Script (no modules, shared global scope) can load them. No other tool is involved.
//   npm run bundle:noble            write the file
//   npm run bundle:noble -- --check exit 1 if the committed file differs from what the installed package produces
'use strict';

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const PACKAGE_DIR = path.join(ROOT, 'node_modules', '@noble', 'hashes');
const OUTPUT = path.join(ROOT, 'src', 'backend', 'NobleHashes.js');
const PINNED_VERSION = '1.8.0';
// From package-lock.json; the build refuses any other tarball.
const PINNED_INTEGRITY = 'sha512-jCs9ldd7NwzpgXDIf6P3+NrHh9/sD6CQdxHyjQI+h/6rDNo88ypBxxz45UDuZHz9r3tNz7N/VInSVoVdtXEI4A==';
// Everything pbkdf2 + sha256 load, in dependency order. "@noble/hashes/crypto" is the non-Node build (crypto.js).
const MODULES = ['crypto.js', 'utils.js', '_md.js', '_u64.js', 'sha2.js', 'hmac.js', 'pbkdf2.js'];
const ALIASES = { '@noble/hashes/crypto': './crypto.js' };

const INDENT = '      ';

// Indented so that no library line starts at column 0: only nobleHashes_ is a top-level declaration.
function indent(source) {
  if (/\\\r?\n/.test(source) || /`[^`]*\n/.test(source.replace(/\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, ''))) {
    fail('a bundled module has a multi-line string; indenting it would change it.');
  }
  return source.replace(/\r\n/g, '\n').trimEnd().split('\n').map((line) => (line ? INDENT + line : line)).join('\n');
}

function fail(message) {
  console.error(`\nError: ${message}\n`);
  process.exit(1);
}

function build() {
  const pkg = JSON.parse(fs.readFileSync(path.join(PACKAGE_DIR, 'package.json'), 'utf8'));
  if (pkg.version !== PINNED_VERSION) fail(`@noble/hashes ${pkg.version} is installed; ${PINNED_VERSION} is pinned.`);
  const lock = JSON.parse(fs.readFileSync(path.join(ROOT, 'package-lock.json'), 'utf8'));
  const locked = lock.packages && lock.packages['node_modules/@noble/hashes'];
  if (!locked || locked.version !== PINNED_VERSION || locked.integrity !== PINNED_INTEGRITY) fail('package-lock.json does not pin the expected @noble/hashes tarball.');

  const license = fs.readFileSync(path.join(PACKAGE_DIR, 'LICENSE'), 'utf8').trim();
  const sources = MODULES.map((name) => {
    const source = fs.readFileSync(path.join(PACKAGE_DIR, name), 'utf8');
    for (const [, required] of source.matchAll(/require\("([^"]+)"\)/g)) {
      const target = ALIASES[required] || required;
      if (!MODULES.includes(target.replace(/^\.\//, ''))) fail(`${name} requires ${required}, which is not bundled.`);
    }
    return { name, source, sha256: crypto.createHash('sha256').update(source).digest('hex') };
  });

  const lines = [
    '// GENERATED by scripts/bundle-noble.js. Do not edit; run "npm run bundle:noble" instead.',
    `// @noble/hashes ${PINNED_VERSION} (npm integrity ${PINNED_INTEGRITY}), audited by Cure53 at 1.0.0 (Jan 2022).`,
    '// Only the modules PBKDF2-HMAC-SHA256 needs, from the package\'s CommonJS build, unchanged except that every line is',
    `// indented by ${INDENT.length} spaces (the sources have no multi-line strings; the tests check the round trip):`,
    ...sources.map((s) => `//   ${s.name} sha256=${s.sha256}`),
    '//',
    ...license.split(/\r?\n/).map((line) => ('// ' + line).trimEnd()),
    '',
    '/**',
    ' * Returns { pbkdf2, sha256 } from the bundled library. The modules are evaluated on first use only, so nothing here',
    ' * runs when other ChoreNest code loads. The name ends in "_", so google.script.run cannot call it.',
    ' */',
    'function nobleHashes_() {',
    '  if (nobleHashes_.cache) return nobleHashes_.cache;',
    '  const factories = {',
    ...sources.flatMap((s) => [`    './${s.name}': function (module, exports, require) {`, indent(s.source), '    },']),
    '  };',
    `  const aliases = ${JSON.stringify(ALIASES)};`,
    '  const loaded = {};',
    '  function load(name) {',
    '    const key = aliases[name] || name;',
    '    if (!Object.prototype.hasOwnProperty.call(factories, key)) throw new Error("Not bundled: " + name);',
    '    if (!loaded[key]) {',
    '      const module = { exports: {} };',
    '      loaded[key] = module;',
    '      factories[key].call(module.exports, module, module.exports, load);',
    '    }',
    '    return loaded[key].exports;',
    '  }',
    "  const pbkdf2 = load('./pbkdf2.js');",
    "  const sha2 = load('./sha2.js');",
    '  nobleHashes_.cache = Object.freeze({ pbkdf2: pbkdf2.pbkdf2, sha256: sha2.sha256 });',
    '  return nobleHashes_.cache;',
    '}',
    '',
  ];
  return lines.join('\n');
}

if (require.main === module) {
  const output = build();
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(OUTPUT) ? fs.readFileSync(OUTPUT, 'utf8').replace(/\r\n/g, '\n') : '';
    if (current !== output) fail('src/backend/NobleHashes.js is out of date. Run "npm run bundle:noble".');
    console.log('src/backend/NobleHashes.js matches @noble/hashes ' + PINNED_VERSION + '.');
  } else {
    fs.writeFileSync(OUTPUT, output);
    console.log(`Wrote ${path.relative(ROOT, OUTPUT)} (${output.length} bytes) from @noble/hashes ${PINNED_VERSION}.`);
  }
}

module.exports = { build, MODULES, PINNED_VERSION, PINNED_INTEGRITY, INDENT, PACKAGE_DIR };
